package net.civeira.phylax.features.document.templatesnippet.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.features.document.templatesnippet.application.visibility.TemplateSnippetFixedPropertiesProposal;

public class FixTenantExcludingRoot {

  /**
   * Constant for platformAdmin field
   *
   * @autogenerated VisibilityPolicyGenerator
   */
  private static final String ROL_PLATFORM_ADMIN = "platform:admin";

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param fixed
   */
  public void fixedFields(@Observes TemplateSnippetFixedPropertiesProposal fixed) {
    Actor actor = fixed.getActor();
    if (!actor.hasRole(ROL_PLATFORM_ADMIN)) {
      fixed.add("tenant");
    }
  }
}
